    /// Upon receipt of this command, the server MAY update its UTCTime Attribute to match the time specified in the
    /// command.
    #[derive(Debug, Clone, PartialEq, Eq, Hash, Default)]
    #[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
    #[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
    #[cfg_attr(all(feature = "serde", feature = "deny-unknown-fields"), serde(deny_unknown_fields))]
    #[cfg_attr(
        all(feature = "schemars", feature = "deny-unknown-fields"),
        schemars(deny_unknown_fields)
    )]
    pub struct SetUtcTime {
        pub utc_time: types::EpochUs,
        pub granularity: super::GranularityEnum,
        #[cfg_attr(feature = "serde", serde(default, skip_serializing_if = "Optional::is_omitted"))]
        #[cfg_attr(all(not(feature = "serde"), feature = "schemars"), schemars(default))]
        pub time_source: Optional<super::TimeSourceEnum>,
    }

    impl SetUtcTime {
        pub const CLUSTER_ID: ClusterId = super::TimeSynchronizationCluster::CLUSTER_ID;
        pub const COMMAND_ID: CommandId = CommandId::new(0x00);
        pub const DIRECTION: CommandDirection = CommandDirection::ClientToServer;
        pub const FIELD_GRANULARITY: FieldId = FieldId::new(0x1);
        pub const FIELD_TIME_SOURCE: FieldId = FieldId::new(0x2);
        pub const FIELD_UTC_TIME: FieldId = FieldId::new(0x0);
        pub const NAME: &'static str = "SetUtcTime";

        #[must_use]
        pub fn new(utc_time: impl Into<types::EpochUs>, granularity: impl Into<super::GranularityEnum>) -> Self {
            Self {
                utc_time: utc_time.into(),
                granularity: granularity.into(),
                time_source: Optional::Omitted,
            }
        }

        #[must_use]
        pub fn with_time_source(mut self, time_source: impl Into<super::TimeSourceEnum>) -> Self {
            self.time_source = Optional::Present(time_source.into());
            self
        }

        #[must_use]
        pub fn into_fields(self) -> Vec<(FieldId, AttributeValue)> {
            let mut fields = Vec::with_capacity(3);
            fields.push((Self::FIELD_UTC_TIME, AttributeValue::from(self.utc_time)));
            fields.push((Self::FIELD_GRANULARITY, AttributeValue::from(self.granularity)));
            if let Optional::Present(v) = self.time_source {
                fields.push((Self::FIELD_TIME_SOURCE, AttributeValue::from(v)));
            }
            fields
        }

        pub(crate) fn decode_fields(
            fields: Vec<(FieldId, AttributeValue)>,
        ) -> Result<Self, (Option<FieldId>, MatterStatus)> {
            let mut utc_time = None;
            let mut granularity = None;
            let mut time_source = None;
            for (fid, fval) in fields {
                match fid.raw() {
                    0 => {
                        if utc_time.is_some() {
                            return Err((Some(fid), MatterStatus::ConstraintError));
                        }
                        (|| -> Result<(), MatterStatus> {
                            let decoded = <types::EpochUs>::try_from(fval)?;
                            utc_time = Some(decoded);
                            Ok(())
                        })()
                        .map_err(|st| (Some(fid), st))?;
                    }
                    1 => {
                        if granularity.is_some() {
                            return Err((Some(fid), MatterStatus::ConstraintError));
                        }
                        (|| -> Result<(), MatterStatus> {
                            let decoded = <super::GranularityEnum>::try_from(fval)?;
                            granularity = Some(decoded);
                            Ok(())
                        })()
                        .map_err(|st| (Some(fid), st))?;
                    }
                    2 => {
                        if time_source.is_some() {
                            return Err((Some(fid), MatterStatus::ConstraintError));
                        }
                        (|| -> Result<(), MatterStatus> {
                            let decoded = <super::TimeSourceEnum>::try_from(fval)?;
                            time_source = Some(decoded);
                            Ok(())
                        })()
                        .map_err(|st| (Some(fid), st))?;
                    }
                    _ => return Err((Some(fid), MatterStatus::ConstraintError)),
                }
            }
            Ok(Self {
                utc_time: utc_time.ok_or((Some(FieldId::new(0)), MatterStatus::InvalidCommand))?,
                granularity: granularity.ok_or((Some(FieldId::new(1)), MatterStatus::InvalidCommand))?,
                time_source: Optional::from(time_source),
            })
        }
    }

    crate::impl_matter_command!(SetUtcTime, super::TimeSynchronizationCluster, (), false);
